// Scratch reference AES (spec validation only, not a deliverable).
const SBOX = new Uint8Array(256);
const INV_SBOX = new Uint8Array(256);
(function buildSbox() {
  // Multiplicative inverse in GF(2^8) mod 0x11B, then the affine transform.
  const inv = new Uint8Array(256);
  const mul = (a, b) => {
    let p = 0;
    for (let i = 0; i < 8; i++) {
      if (b & 1) p ^= a;
      const hi = a & 0x80;
      a = (a << 1) & 0xff;
      if (hi) a ^= 0x1b;
      b >>= 1;
    }
    return p;
  };
  for (let i = 1; i < 256; i++) {
    for (let j = 1; j < 256; j++) if (mul(i, j) === 1) { inv[i] = j; break; }
  }
  inv[0] = 0;
  for (let i = 0; i < 256; i++) {
    const b = inv[i];
    const rot = (x, n) => ((x << n) | (x >>> (8 - n))) & 0xff;
    const s = b ^ rot(b, 1) ^ rot(b, 2) ^ rot(b, 3) ^ rot(b, 4) ^ 0x63;
    SBOX[i] = s;
    INV_SBOX[s] = i;
  }
})();

const xtime = (a) => ((a << 1) ^ ((a & 0x80) ? 0x1b : 0)) & 0xff;
function gmul(a, b) {
  let p = 0;
  for (let i = 0; i < 8; i++) {
    if (b & 1) p ^= a;
    a = xtime(a);
    b >>= 1;
  }
  return p & 0xff;
}

const RCON = [0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80, 0x1b, 0x36, 0x6c, 0xd8, 0xab, 0x4d];

function expandKey(key) {
  const Nk = key.length / 4;
  if (![4, 6, 8].includes(Nk)) throw new Error('Invalid key size');
  const Nr = Nk + 6;
  const w = [];
  for (let i = 0; i < Nk; i++) w.push([key[4 * i], key[4 * i + 1], key[4 * i + 2], key[4 * i + 3]]);
  for (let i = Nk; i < 4 * (Nr + 1); i++) {
    let t = w[i - 1].slice();
    if (i % Nk === 0) {
      t = [t[1], t[2], t[3], t[0]].map((b) => SBOX[b]);       // RotWord + SubWord
      t[0] ^= RCON[i / Nk - 1];                                // Rcon
    } else if (Nk === 8 && i % Nk === 4) {
      t = t.map((b) => SBOX[b]);                               // extra SubWord for AES-256
    }
    w.push(w[i - Nk].map((b, j) => b ^ t[j]));
  }
  return { w, Nr };
}

// state[r][c] = input[r + 4*c]  (column-major fill)
function toState(bytes) {
  const s = [[], [], [], []];
  for (let i = 0; i < 16; i++) s[i % 4][(i / 4) | 0] = bytes[i];
  return s;
}
function fromState(s) {
  const out = new Uint8Array(16);
  for (let i = 0; i < 16; i++) out[i] = s[i % 4][(i / 4) | 0];
  return out;
}

function addRoundKey(s, w, round) {
  for (let c = 0; c < 4; c++) for (let r = 0; r < 4; r++) s[r][c] ^= w[round * 4 + c][r];
}
function subBytes(s, box) {
  for (let r = 0; r < 4; r++) for (let c = 0; c < 4; c++) s[r][c] = box[s[r][c]];
}
function shiftRows(s) {
  for (let r = 1; r < 4; r++) s[r] = s[r].slice(r).concat(s[r].slice(0, r));
}
function invShiftRows(s) {
  for (let r = 1; r < 4; r++) s[r] = s[r].slice(4 - r).concat(s[r].slice(0, 4 - r));
}
function mixColumns(s) {
  for (let c = 0; c < 4; c++) {
    const a = [s[0][c], s[1][c], s[2][c], s[3][c]];
    s[0][c] = gmul(a[0], 2) ^ gmul(a[1], 3) ^ a[2] ^ a[3];
    s[1][c] = a[0] ^ gmul(a[1], 2) ^ gmul(a[2], 3) ^ a[3];
    s[2][c] = a[0] ^ a[1] ^ gmul(a[2], 2) ^ gmul(a[3], 3);
    s[3][c] = gmul(a[0], 3) ^ a[1] ^ a[2] ^ gmul(a[3], 2);
  }
}
function invMixColumns(s) {
  for (let c = 0; c < 4; c++) {
    const a = [s[0][c], s[1][c], s[2][c], s[3][c]];
    s[0][c] = gmul(a[0], 14) ^ gmul(a[1], 11) ^ gmul(a[2], 13) ^ gmul(a[3], 9);
    s[1][c] = gmul(a[0], 9) ^ gmul(a[1], 14) ^ gmul(a[2], 11) ^ gmul(a[3], 13);
    s[2][c] = gmul(a[0], 13) ^ gmul(a[1], 9) ^ gmul(a[2], 14) ^ gmul(a[3], 11);
    s[3][c] = gmul(a[0], 11) ^ gmul(a[1], 13) ^ gmul(a[2], 9) ^ gmul(a[3], 14);
  }
}

export function encryptBlock(key, block) {
  const { w, Nr } = expandKey(key);
  const s = toState(block);
  addRoundKey(s, w, 0);
  for (let round = 1; round < Nr; round++) {
    subBytes(s, SBOX); shiftRows(s); mixColumns(s); addRoundKey(s, w, round);
  }
  subBytes(s, SBOX); shiftRows(s); addRoundKey(s, w, Nr);
  return fromState(s);
}

export function decryptBlock(key, block) {
  const { w, Nr } = expandKey(key);
  const s = toState(block);
  addRoundKey(s, w, Nr);
  for (let round = Nr - 1; round >= 1; round--) {
    invShiftRows(s); subBytes(s, INV_SBOX); addRoundKey(s, w, round); invMixColumns(s);
  }
  invShiftRows(s); subBytes(s, INV_SBOX); addRoundKey(s, w, 0);
  return fromState(s);
}

export function pyRepr(bytes) {
  const has = (v) => bytes.includes(v);
  const q = has(0x27) && !has(0x22) ? '"' : "'";
  let out = 'b' + q;
  for (const b of bytes) {
    if (b === q.charCodeAt(0)) out += '\\' + q;
    else if (b === 0x5c) out += '\\\\';
    else if (b === 0x09) out += '\\t';
    else if (b === 0x0a) out += '\\n';
    else if (b === 0x0d) out += '\\r';
    else if (b < 0x20 || b >= 0x7f) out += '\\x' + b.toString(16).padStart(2, '0');
    else out += String.fromCharCode(b);
  }
  return out + q;
}

const hex = (b) => Buffer.from(b).toString('hex');
const unhex = (h) => Uint8Array.from(h.match(/../g).map((x) => parseInt(x, 16)));
const utf8 = (s) => new Uint8Array(Buffer.from(s, 'utf8'));

// ---- FIPS-197 Appendix C known-answer tests ----
const KATS = [
  ['C.1 AES-128', '000102030405060708090a0b0c0d0e0f', '69c4e0d86a7b0430d8cdb78070b4c55a'],
  ['C.2 AES-192', '000102030405060708090a0b0c0d0e0f1011121314151617', 'dda97ca4864cdfe06eaf70a0ec0d7191'],
  ['C.3 AES-256', '000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f', '8ea2b7ca516745bfeafc49904b496089'],
];
const PT = '00112233445566778899aabbccddeeff';
console.log('--- FIPS-197 Appendix C ---');
for (const [name, k, ct] of KATS) {
  const got = hex(encryptBlock(unhex(k), unhex(PT)));
  const back = hex(decryptBlock(unhex(k), unhex(ct)));
  console.log(`${name}: enc=${got} ${got === ct ? 'OK' : 'MISMATCH exp=' + ct} | dec=${back === PT ? 'OK' : 'MISMATCH ' + back}`);
}
// FIPS-197 Appendix B
{
  const got = hex(encryptBlock(unhex('2b7e151628aed2a6abf7158809cf4f3c'), unhex('3243f6a8885a308d313198a2e0370734')));
  console.log(`B  AES-128: enc=${got} ${got === '3925841d02dc09fbdc118597196a0b32' ? 'OK' : 'MISMATCH'}`);
}

// ---- CBC chaining against the oracle ----
const args = process.argv.slice(2);
if (args.length === 4) {
  const [k, iv, d1, d2] = args.map(utf8);
  const xor = (a, b) => a.map((v, i) => v ^ b[i]);
  const c1 = encryptBlock(k, xor(d1, iv));
  const c2 = encryptBlock(k, xor(d2, c1));
  console.log('--- CBC ---');
  console.log(pyRepr(c1));
  console.log(pyRepr(c2));
  console.log('hex1=' + hex(c1) + ' hex2=' + hex(c2));
}

